 const list=a.tracks.map((t,i)=>{const song=M.songs.find(x=>x.id===t.id),collected=open(t.id),available=M.eligible(s,t.id);return `<article class="row song-row ${collected?'collected':available?'available':'is-locked'}"><span class="num">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(song.title)}</h3><small>${t.instrumental?'반주 트랙 · ':t.reissue?'베스트 앨범 재수록 · ':''}${song.hint.replace('열려요.','퀴즈가 열려요.')}</small><div class="track-state">${collected?'수집 완료 · 준비도 '+pct(t.id)+'%':available?'조건 달성 · 한 문제를 풀고 수집해요':'아직 잠긴 곡'}</div></div>${button(collected?'연습하기':available?'곡 만나기':'잠김',collected?'pick':'challenge',collected?t.id:'song:'+t.id,available&&!collected?'primary':'',!collected&&!available)}</article>`;}).join('');
 return `${mark('ALBUM JOURNEY')}<h2>앨범을 한 장씩 펼쳐요</h2><p>앞 앨범의 전곡을 모으면 다음 앨범을 해금할 수 있어요.<br>앨범 해금은 의상, 전곡 수집과 전곡 준비도 100%는 각각 배지로 남아요.</p>${albumJourney()}${panel(`${mark(a.type)}<div class="line"><h2>${a.name}</h2><span class="status-pill">${n} / ${size}트랙</span></div>${a.id==='rebloom'?'<p class="collected-note">Rebloom은 당시 발매 기록을 따라 수집합니다. 도트 의상은 현재 세 멤버의 재해석이며 당시 멤버 구성과 다릅니다.</p>':''}${!unlocked?`<p>${M.albumAvailable(s,a.id)?'이전 앨범을 모두 모았어요. 다음 장을 열어보세요.':M.albums[idx-1].name+' 전곡을 모으면 열 수 있어요.'}</p>${button('앨범 해금하고 의상 받기','unlock-album',a.id,'primary',!M.albumAvailable(s,a.id))}`:`<div class="album-progress"><strong>${n===size?'전곡 수집 배지 획득!':'한 트랙씩 모으는 중'}</strong>${bars(100*n/size)}<small>${a.id==='first-mind'?'기존 이야기와 연습을 따라 곡을 열어요.':'곡을 수집한 뒤 한 번 연습하면 다음 곡의 퀴즈가 열려요.'}</small></div>`}${a.id==='see-you-again'?'<p class="private-note">재수록곡도 이 앨범의 별도 수집 칸으로 표시합니다.</p>':''}<div class="album-story-link">${button('이 시기의 이야기·이벤트 보기','stories-album',a.id)}<small>${M.storyEntries.filter(e=>e.album===a.id&&M.storyAvailable(s,e.id)&&!M.storyDone(s,e.id)).length}개 새 이야기</small></div><div class="song-list">${list}</div>${link('앨범 수록곡 원본',a.source)}${n===size&&idx<M.albums.length-1?`<div class="next-album">${button('다음 앨범으로 →','album-view',M.albums[idx+1].id,'primary')}</div>`:''}`)}`;
